from collections import Counter

def top(words, n=1):
    return Counter(words).most_common(n)

menu = {"tea": 10, "chai": 15, "coffee": 25}
orders = ["tea", "chai", "tea", "coffee", "tea"]
bill = sum(menu[o] for o in orders)
